// Core tests: the 7 literal core cases from the fixed spec's
// fixtures.json (vendored verbatim at test/fixtures.json from spec
// candidate 2a21f1a0ebde740d0874f62ccd50435517532cc9; expected values
// taken verbatim, never generated by the product), plus hand-derived
// endpoint, rounding, boundary, and validation-order cases. The SPEC's
// own rules are the oracle; every extra expected value below was
// computed by hand from those rules.

import assert from "node:assert/strict";
import test from "node:test";
import { run } from "../public/js/core/zones.mjs";
import fixtures from "./fixtures.json" with { type: "json" };

const coreCases = fixtures.cases.filter((entry) => entry.kind === "core");
for (const entry of coreCases) {
  test(`fixture ${entry.id}: ${entry.purpose}`, () => {
    assert.deepEqual(run(entry.input), entry.expected);
  });
}

// Hand-derived endpoint: age 100 (the legal maximum). fox = 120;
// Tanaka tenths 2080 - 700 = 1380 -> 138. Boundaries for used 138:
// b(5)=69, b(6)=83, b(7)=97, b(8)=110, b(9)=124, b(10)=138.
test("hand-derived endpoint: age 100", () => {
  assert.deepEqual(run({ age: "100", measuredMaxHr: "", restingHr: "" }), {
    ok: true,
    result: {
      maxHr: { fox: 120, tanaka: 138, used: 138, source: "tanaka" },
      zones: [
        { zone: 1, pctLow: 50, pctHigh: 60, lowBpm: 69, highBpm: 83 },
        { zone: 2, pctLow: 60, pctHigh: 70, lowBpm: 84, highBpm: 97 },
        { zone: 3, pctLow: 70, pctHigh: 80, lowBpm: 98, highBpm: 110 },
        { zone: 4, pctLow: 80, pctHigh: 90, lowBpm: 111, highBpm: 124 },
        { zone: 5, pctLow: 90, pctHigh: 100, lowBpm: 125, highBpm: 138 },
      ],
      karvonen: null,
    },
  });
});

