// The SPEC's structural invariant, checked as a property over legal
// inputs (the invariant itself is the SPEC's stated rule, not output
// copied from the implementation): five zones, continuous with no gap
// or overlap, Z5 ends exactly at the used maximum — for both tables.
function assertContinuous(zones, used, label) {
  assert.equal(zones.length, 5, label);
  for (let index = 0; index < 5; index += 1) {
    assert.equal(zones[index].zone, index + 1, label);
    assert.equal(zones[index].pctLow, (index + 5) * 10, label);
    assert.equal(zones[index].pctHigh, (index + 6) * 10, label);
    if (index > 0) {
      assert.equal(zones[index].lowBpm, zones[index - 1].highBpm + 1, label);
    }
  }
  assert.equal(zones[4].highBpm, used, label);
}

test("zone continuity invariant across all legal ages and measured values", () => {
  for (let age = 10; age <= 100; age += 1) {
    const outcome = run({ age: String(age), measuredMaxHr: "", restingHr: "" });
    assert.equal(outcome.ok, true, `age ${age}`);
    assertContinuous(outcome.result.zones, outcome.result.maxHr.used, `age ${age}`);
  }
  for (let measured = 100; measured <= 230; measured += 1) {
    const outcome = run({ age: "", measuredMaxHr: String(measured), restingHr: "60" });
    assert.equal(outcome.ok, true, `measured ${measured}`);
    assertContinuous(outcome.result.zones, measured, `measured ${measured}`);
    assertContinuous(outcome.result.karvonen.zones, measured, `karvonen ${measured}`);
  }
});

test("resting == used fails; resting == used - 1 succeeds and ends at used", () => {
  // Both resting values are inside the field's own 30-120 range, so the
  // per-field checks pass and the cross-field rule decides (compare the
  // fixture resting-not-below-max: resting 115 vs used 110).
  assert.deepEqual(run({ age: "", measuredMaxHr: "120", restingHr: "120" }), {
    ok: false,
    error: { code: "RESTING_NOT_BELOW_MAX", field: "restingHr", row: null },
  });
  const outcome = run({ age: "", measuredMaxHr: "120", restingHr: "119" });
  assert.equal(outcome.ok, true);
  assert.equal(outcome.result.karvonen.reserve, 1);
  assertContinuous(outcome.result.karvonen.zones, 120, "reserve 1");
});

const valid = { age: "40", measuredMaxHr: "", restingHr: "60" };
const errorOf = (input) => run(input).error;

test("SCHEMA: non-objects, arrays, missing, extra, wrong types, accessors", () => {
  const schema = { code: "SCHEMA", field: null, row: null };
  assert.deepEqual(errorOf(null), schema);
  assert.deepEqual(errorOf("40"), schema);
  assert.deepEqual(errorOf(["40", "", "60"]), schema);
  assert.deepEqual(errorOf({ age: "40", measuredMaxHr: "" }), schema);
  assert.deepEqual(errorOf({ ...valid, extra: "1" }), schema);
  assert.deepEqual(errorOf({ ...valid, age: 40 }), schema);
  assert.deepEqual(errorOf({ ...valid, restingHr: null }), schema);
  const withAccessor = { measuredMaxHr: "", restingHr: "60" };
  Object.defineProperty(withAccessor, "age", {
    enumerable: true,
    get() {
      return "40";
    },
  });
  assert.deepEqual(errorOf(withAccessor), schema);
});

test("validation order: age, then measuredMaxHr, then restingHr", () => {
  assert.deepEqual(errorOf({ age: "9", measuredMaxHr: "99", restingHr: "29" }), {
    code: "RANGE",
    field: "age",
    row: null,
  });
  assert.deepEqual(errorOf({ age: "", measuredMaxHr: "99", restingHr: "29" }), {
    code: "RANGE",
    field: "measuredMaxHr",
    row: null,
  });
  assert.deepEqual(errorOf({ age: "40", measuredMaxHr: "", restingHr: "abc" }), {
    code: "INTEGER_FORMAT",
    field: "restingHr",
    row: null,
  });
});

test("a filled-but-invalid age errors even when a measured maximum is present", () => {
  assert.deepEqual(errorOf({ age: "9", measuredMaxHr: "180", restingHr: "" }), {
    code: "RANGE",
    field: "age",
    row: null,
  });
  assert.deepEqual(errorOf({ age: "abc", measuredMaxHr: "180", restingHr: "" }), {
    code: "INTEGER_FORMAT",
    field: "age",
    row: null,
  });
});

test("per-field order: capacity before grammar; per-field before cross-field", () => {
  assert.deepEqual(errorOf({ ...valid, age: "123456789" }), {
    code: "INPUT_LIMIT",
    field: "age",
    row: null,
  });
  // restingHr is invalid AND no maximum source exists: the per-field
  // error wins over the cross-field EMPTY check.
  assert.deepEqual(errorOf({ age: "", measuredMaxHr: "", restingHr: "abc" }), {
    code: "INTEGER_FORMAT",
    field: "restingHr",
    row: null,
  });
  assert.deepEqual(errorOf({ age: "", measuredMaxHr: "", restingHr: "" }), {
    code: "EMPTY",
    field: "age",
    row: null,
  });
});

test("integer grammar rejects signs, spaces, leading zeros, decimals, full-width digits", () => {
  for (const bad of ["035", "00", "35.5", "+35", "-35", " 35", "35 ", "1e2", "３５", "٣٥"]) {
    assert.deepEqual(
      errorOf({ ...valid, age: bad }),
      { code: "INTEGER_FORMAT", field: "age", row: null },
      `age ${JSON.stringify(bad)}`,
    );
  }
  // "0" is grammatical but below every field's range.
  assert.deepEqual(errorOf({ ...valid, age: "0" }), {
    code: "RANGE",
    field: "age",
    row: null,
  });
});

test("range edges just outside each bound", () => {
  assert.deepEqual(errorOf({ ...valid, age: "101" }), {
    code: "RANGE",
    field: "age",
    row: null,
  });
  assert.deepEqual(errorOf({ age: "", measuredMaxHr: "99", restingHr: "" }), {
    code: "RANGE",
    field: "measuredMaxHr",
    row: null,
  });
  assert.deepEqual(errorOf({ age: "", measuredMaxHr: "231", restingHr: "" }), {
    code: "RANGE",
    field: "measuredMaxHr",
    row: null,
  });
  assert.deepEqual(errorOf({ ...valid, restingHr: "29" }), {
    code: "RANGE",
    field: "restingHr",
    row: null,
  });
  assert.deepEqual(errorOf({ ...valid, restingHr: "121" }), {
    code: "RANGE",
    field: "restingHr",
    row: null,
  });
});

test("results contain no floating point values", () => {
  for (const entry of coreCases) {
    if (!entry.expected.ok) continue;
    const outcome = run(entry.input);
    const walk = (value) => {
      if (typeof value === "number") assert.ok(Number.isInteger(value), entry.id);
      else if (value !== null && typeof value === "object") {
        for (const nested of Object.values(value)) walk(nested);
      }
    };
    walk(outcome.result);
  }
});
